// @pit: {"label": "Rewrite comment footer as a collapsed details block with read commands"}
async ({ workspace: { read, edit } }) => {
  const r = await read("src/formatting.ts", { format: "raw" });
  let c = r.content.replace(`/** \`ref\`, the thread's ref (e.g. refs/pi/threads/42), adds a footer saying where the thread is stored. */
function footer(ref: string | undefined): string {
	return ref
		? \`\\n\\n---\\n🧵 Thread state: \\\`\${ref}\\\` (\\\`git fetch origin \${ref}\\\`)\`
		: "";
}
`, "");
  const footer = `
/**
 * \`ref\`, the thread's ref (e.g. refs/pi/threads/42), adds a footer: where the conversation is stored, collapsed, with
 * the git commands that read it from a clone (#80).
 */
function footer(ref: string | undefined): string {
	if (!ref) {
		return "";
	}
	return [
		"",
		"",
		\`<sub><details><summary>🧵 This conversation is stored in git on <code>\${ref}</code></summary>\`,
		"",
		\`Read it from a clone of this repository ([more](\${READ_A_THREAD})):\`,
		"",
		"\`\`\`bash",
		...readCommands(ref, "origin"),
		"\`\`\`",
		"",
		"</details></sub>",
	].join("\\n");
}
`;
  if (c === r.content) return "footer not found";
  // Place the footer after readCommands, which it uses.
  c = c.replace("/** How to read the thread with git, for the workflow log. */", footer.trimStart() + "\n/** How to read the thread with git, for the workflow log. */");
  // Comment formatters after the footer.
  const success = `export function formatSuccessComment(response: string, ref?: string): string {
	return \`### 🤖 pi Response\\n\\n\${response}\${footer(ref)}\`;
}

export function formatErrorComment(error: string, ref?: string): string {
	return \`### ❌ pi Error\\n\\nFailed to process request: \${error}\${footer(ref)}\`;
}

`;
  if (!c.includes(success)) return "formatters not found";
  c = c.replace(success, "").replace("/** How to read the thread with git, for the workflow log. */", success + "/** How to read the thread with git, for the workflow log. */");
  await edit("src/formatting.ts", { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  return c.slice(0, 2600);
}
